function run_q7_aoe_subject001_all()
% Q7 AOE subject001 interaction contrast using validated Q5 AOE GLM.
sid='subject001';repo=fileparts(fileparts(fileparts(mfilename('fullpath'))));glm='C:\aliceproject\GLM';fl=fullfile(glm,'first_level');srcroot=fullfile(repo,'results','q5_intrinsic_aoe','cohort_specification',sid);root=fullfile(repo,'results','q7_interaction_aoe','cohort_specification',sid);if ~isfolder(root),mkdir(root);end;addpath(fl);addpath(fullfile(glm,'toolboxes','spm'));addpath(genpath(fullfile(glm,'toolboxes','NIRS_SPM_v4_r1')));df=fullfile(fl,'nirs_spm_inputs_v2_fulltimeline_trial1',sid,[sid '_nirs_data.mat']);M=readtable(fullfile(fl,'nirs_spm_inputs',sid,[sid '_channel_metadata.csv']),'TextType','string');
for hb=["HbO","HbR"]
 sf=fullfile(srcroot,char(hb),sprintf('SPM_indiv_%s.mat',hb));L=load(sf,'SPM_nirs');S=L.SPM_nirs;B=double(S.nirs.beta);N=string(S.xX.name(:));targets=["LILEAOE","HILEAOE","LIHEAOE","HIHEAOE"];k=zeros(4,1);for i=1:4,k(i)=find(contains(N,targets(i)),1);end;c=zeros(5,1);c(k)=[1 -1 -1 1];rss=double(S.nirs.ResSS);if ~isvector(rss),rss=diag(rss)';end;dfree=double(S.xX.erdf);b=c'*B;se=sqrt(max((c'*double(S.xX.Bcov)*c).*(rss/dfree),0));t=b./se;p=betainc(dfree./(dfree+t.^2),dfree/2,.5);q=bh(p);hr=fullfile(root,char(hb));if ~isfolder(hr),mkdir(hr);end;R=table(repmat(string(sid),61,1),repmat(hb,61,1),(1:61)',string(M.channel_id),string(M.channel_type),string(M.roi),string(M.laterality),b(:),se(:),t(:),p(:),q(:),repmat(join(string(c'),' '),61,1),'VariableNames',{'subject_id','hemoglobin','channel_index','channel_id','channel_type','roi','laterality','contrast_beta','contrast_se','contrast_t','contrast_p_two_sided','contrast_q_bh61','contrast_vector'});writetable(R,fullfile(root,sprintf('%s_%s_q7_interaction_aoe_channel_contrasts.csv',sid,hb)));writetable(table(hb,61,sum(p<.05),sum(q<.05),median(b),'VariableNames',{'hemoglobin','n_channels','n_p_lt_005','n_q_bh61_lt_005','median_contrast_beta'}),fullfile(root,sprintf('%s_%s_q7_interaction_aoe_contrast_summary.csv',sid,hb)));copyfile(fullfile(srcroot,char(hb),sprintf('%s_%s_q5_aoe_convolved_design.csv',sid,hb)),fullfile(hr,sprintf('%s_%s_q7_interaction_aoe_convolved_design.csv',sid,hb)));copyfile(fullfile(srcroot,char(hb),sprintf('%s_%s_q5_aoe_vif.csv',sid,hb)),fullfile(hr,sprintf('%s_%s_q7_interaction_aoe_vif.csv',sid,hb)));data=load(df,'nirs_data');field='dxyData';if hb=="HbO",field='oxyData';end;y=double(data.nirs_data.(field)(:,1));yf=spm_filter_HPF_LPF_WMDL(S.xX.K,y);Xf=full(S.xX.xKXs.X);fit=Xf*B(:,1);res=yf-fit;tsec=(0:size(S.xX.X,1)-1)'*double(S.xY.RT);figdir=fullfile(hr,'figures');if ~isfolder(figdir),mkdir(figdir);end;h=(0:size(S.xBF.bf,1)-1)'*double(S.xBF.dt);f=figure('Visible','off','Color','w');plot(h,S.xBF.bf(:,1),'Color',[0 0.35 0.7],'LineWidth',1.8);grid on;xlabel('Time after event onset (s)');ylabel('HRF amplitude');title(sprintf('Q7 AOE canonical HRF (%s)',hb),'Color','k');exportgraphics(f,fullfile(figdir,sprintf('%s_%s_q7_interaction_aoe_canonical_hrf.png',sid,hb)),'Resolution',220);close(f);task=~contains(lower(N),'constant');f=figure('Visible','off','Color','w');imagesc(S.xX.X(:,task)');axis tight;colormap(f,parula);colorbar;yticks(1:4);yticklabels(N(task));xlabel('Scan');ylabel('HRF-convolved task regressor');title(sprintf('%s Q7 AOE regressor heatmap (%s)',sid,hb),'Color','k');exportgraphics(f,fullfile(figdir,sprintf('%s_%s_q7_interaction_aoe_convolved_regressor_heatmap.png',sid,hb)),'Resolution',220);close(f);f=figure('Visible','off','Color','w');plot(tsec,S.xX.X(:,task),'LineWidth',1.1);grid on;xlabel('Time (s)');ylabel('Task regressor');title(sprintf('%s Q7 AOE four convolved regressors (%s)',sid,hb),'Color','k');legend(N(task),'Location','eastoutside');exportgraphics(f,fullfile(figdir,sprintf('%s_%s_q7_interaction_aoe_convolved_regressor_timeseries.png',sid,hb)),'Resolution',220);close(f);f=figure('Visible','off','Color','w');tiledlayout(3,1);nexttile;plot(tsec,yf);hold on;plot(tsec,fit,'LineWidth',1.2);grid on;title(sprintf('%s channel 1 %s: observed and fitted signal',sid,hb));legend('Observed','GLM fitted');nexttile;plot(tsec,res);hold on;yline(0,'--k');grid on;title('GLM residual');nexttile;plot(tsec,S.xX.X(:,task));grid on;title('Q7 AOE interaction model regressors');legend(N(task),'Location','eastoutside');exportgraphics(f,fullfile(figdir,sprintf('%s_channel01_%s_q7_interaction_aoe_fit.png',sid,hb)),'Resolution',220);close(f);
end
end
function q=bh(p),q=nan(size(p));v=isfinite(p);pv=p(v);[s,o]=sort(pv(:));m=numel(s);z=min(1,flipud(cummin(flipud(s.*m./(1:m)'))));zv=zeros(size(pv));zv(o)=z;q(v)=zv;end
